<section class="section-head"><div><span class="eyebrow">WORLD → CLUB</span><h1>Albero organizzativo mondiale</h1><p>Gerarchia normalizzata, conservando i nomi e le strutture originali di ogni Paese.</p></div></section>
<div id="dxTree" class="card">Caricamento…</div>
<script>(async()=>{const root=document.getElementById('dxTree');async function load(parent,box){let u='api-world-hierarchy.php'+(parent?'?parent='+encodeURIComponent(parent):'');let a=await fetch(u).then(r=>r.json());box.innerHTML='';a.forEach(n=>{let d=document.createElement('div');d.className='tree-row';d.innerHTML=`<button class="tree-open">＋</button><i style="background:${n.rank_color}"></i><div><b>${n.entity_name}</b><small>${n.network_level} · ${n.sic_id}</small></div><span>${n.direct_children}</span>`;box.appendChild(d);let child=document.createElement('div');child.className='tree-children hidden';box.appendChild(child);d.querySelector('button').onclick=async()=>{if(child.classList.contains('hidden')){child.classList.remove('hidden');await load(n.sic_id,child);d.querySelector('button').textContent='−'}else{child.classList.add('hidden');d.querySelector('button').textContent='＋'}}})}await load('',root)})();</script>
<style>.tree-row{display:grid;grid-template-columns:34px 12px 1fr auto;gap:9px;align-items:center;padding:9px;border-bottom:1px solid #edf2f7}.tree-row button{border:0;background:#eaf2f7;border-radius:9px;width:30px;height:30px}.tree-row i{width:10px;height:10px;border-radius:50%}.tree-row small{display:block;color:#718596}.tree-children{margin-left:22px;border-left:2px solid #dce8ee;padding-left:7px}</style>
